"""`proto.lock`: field numbers frozen once assigned, and numbers of removed fields.

Without an explicit number, a field gets the smallest number never used in the message the
first time it is locked, wherever it is declared, and keeps it. A removed field's number and
name become reserved, so they are never reused::

    # proto.lock — generated by `fastgrpc3 lock`, commit it
    version = 1

    [messages."orders.v1.OrderReply"]
    reserved = [4]
    reserved_names = ["legacy_code"]

    [messages."orders.v1.OrderReply".fields]
    order_number = 1
    status = 2
"""

import json
import tomllib
from collections.abc import Collection, Sequence
from dataclasses import dataclass, field
from pathlib import Path
from typing import Literal

__all__ = [
    "Change",
    "Lock",
    "LockError",
    "MessageLock",
    "assign_numbers",
    "check_number",
]

LOCK_VERSION = 1
MAX_FIELD_NUMBER = 2**29 - 1
IMPLEMENTATION_RESERVED = range(19000, 20000)

Unlocked = Literal["assign", "error"]


class LockError(ValueError):
    """Field numbers that cannot be assigned, or an invalid `proto.lock`."""


@dataclass
class MessageLock:
    """Numbers of one message: current fields, then reserved numbers and names."""

    fields: dict[str, int] = field(default_factory=dict)
    reserved: list[int] = field(default_factory=list)
    reserved_names: list[str] = field(default_factory=list)


@dataclass
class Lock:
    """Content of a `proto.lock` file, keyed by full message name."""

    messages: dict[str, MessageLock] = field(default_factory=dict)

    @classmethod
    def load(cls, path: Path) -> "Lock":
        """Read a lock file; a missing file is an empty lock."""
        if not path.exists():
            return cls()
        return cls.loads(path.read_text(encoding="utf-8"))

    @classmethod
    def loads(cls, text: str) -> "Lock":
        """Parse the TOML text of a lock file."""
        try:
            data = tomllib.loads(text)
        except tomllib.TOMLDecodeError as e:
            raise LockError(f"invalid proto.lock: {e}") from e
        version = data.get("version", LOCK_VERSION)
        if version != LOCK_VERSION:
            raise LockError(f"unsupported proto.lock version {version}")
        messages = {}
        for name, entry in data.get("messages", {}).items():
            messages[name] = MessageLock(
                fields=dict(entry.get("fields", {})),
                reserved=list(entry.get("reserved", [])),
                reserved_names=list(entry.get("reserved_names", [])),
            )
        return cls(messages)

    def dumps(self) -> str:
        """TOML text of the lock, sorted so that diffs stay small."""
        lines = [
            "# proto.lock — generated by `fastgrpc3 lock`, commit it",
            f"version = {LOCK_VERSION}",
        ]
        for name in sorted(self.messages):
            entry = self.messages[name]
            table = f"messages.{json.dumps(name)}"
            if entry.reserved or entry.reserved_names:
                lines += ["", f"[{table}]"]
            if entry.reserved:
                lines.append(f"reserved = {sorted(entry.reserved)}")
            if entry.reserved_names:
                lines.append(f"reserved_names = {json.dumps(sorted(entry.reserved_names))}")
            lines += ["", f"[{table}.fields]"]
            for field_name, number in sorted(entry.fields.items(), key=lambda item: item[1]):
                lines.append(f"{field_name} = {number}")
        return "\n".join(lines) + "\n"

    def save(self, path: Path) -> None:
        """Write the lock file."""
        path.write_text(self.dumps(), encoding="utf-8")


@dataclass(frozen=True, slots=True)
class Change:
    """One difference between the models and the lock, reported by `lock` and `check`."""

    kind: Literal["added", "removed", "renumbered", "message_removed"]
    message: str
    field: str = ""
    number: int = 0

    def __str__(self) -> str:
        if self.kind == "message_removed":
            return f"{self.message}: message removed"
        return f"{self.message}.{self.field}: {self.kind.replace('_', ' ')} ({self.number})"


def check_number(owner: str, number: int) -> None:
    """Reject a field number protobuf does not allow."""
    if not 1 <= number <= MAX_FIELD_NUMBER:
        raise LockError(f"{owner}: field number {number} is not in 1..{MAX_FIELD_NUMBER}")
    if number in IMPLEMENTATION_RESERVED:
        raise LockError(f"{owner}: field numbers 19000-19999 are reserved by protobuf")


def assign_numbers(
    message: str,
    fields: Sequence[tuple[str, int | None]],
    previous: MessageLock | None,
    unlocked: Unlocked = "assign",
    declared: Sequence[tuple[int, int]] = (),
    declared_names: Collection[str] = (),
) -> tuple[MessageLock, list[Change]]:
    """Number the fields of a message from explicit numbers and the previous lock entry.

    `fields` are `(name, explicit number or None)` in declaration order. `declared` and
    `declared_names` are what the model itself reserves (inclusive ranges, names): no field
    may use them. Returns the new lock entry and what changed. With `unlocked="error"`, a
    field that would need a new number raises `LockError` instead.
    """
    previous = previous or MessageLock()
    reserved = set(previous.reserved)
    reserved_names = set(previous.reserved_names)
    numbers: dict[str, int] = {}
    changes: list[Change] = []
    owners: dict[int, str] = {}

    def take(name: str, number: int, source: str) -> None:
        check_number(f"{message}.{name}", number)
        if _in_ranges(number, declared):
            raise LockError(f"{message}.{name}: number {number} is reserved by the model")
        if name in declared_names:
            raise LockError(f"{message}.{name}: the name is reserved by the model")
        if number in owners:
            raise LockError(
                f"{message}: number {number} used by both {owners[number]} and {name} ({source})"
            )
        owners[number] = name
        numbers[name] = number

    pending = []
    for name, explicit in fields:
        locked = previous.fields.get(name)
        if explicit is not None:
            if explicit in reserved:
                raise LockError(
                    f"{message}.{name}: number {explicit} belonged to a removed field "
                    "(reserved in proto.lock)"
                )
            take(name, explicit, "explicit")
            if locked is None:
                changes.append(Change("added", message, name, explicit))
            elif locked != explicit:
                changes.append(Change("renumbered", message, name, explicit))
        elif locked is not None:
            take(name, locked, "proto.lock")
        else:
            pending.append(name)

    if pending and unlocked == "error":
        names = ", ".join(f"{message}.{name}" for name in pending)
        raise LockError(f"no field number for {names}: run `fastgrpc3 lock` or use field(n)")
    # Every number ever locked is in `owners`, `reserved` or the previous fields: the
    # smallest number outside them is safe on the wire.
    taken = {*owners, *reserved, *previous.fields.values()}
    candidate = 1
    for name in pending:
        while (
            candidate in taken
            or candidate in IMPLEMENTATION_RESERVED
            or _in_ranges(candidate, declared)
        ):
            candidate += 1
        take(name, candidate, "new")
        taken.add(candidate)
        changes.append(Change("added", message, name, candidate))

    # A removed or renumbered field leaves its number reserved for good.
    for name, number in previous.fields.items():
        if name not in numbers:
            reserved_names.add(name)
            changes.append(Change("removed", message, name, number))
        if numbers.get(name) != number and number not in owners:
            reserved.add(number)
    reserved_names -= set(numbers)

    entry = MessageLock(numbers, sorted(reserved), sorted(reserved_names))
    return entry, changes


def _in_ranges(number: int, ranges: Sequence[tuple[int, int]]) -> bool:
    return any(start <= number <= end for start, end in ranges)
